INSERT OR IGNORE INTO posts (id, slug, title, category, category_slug, filters_json, date, date_display, read_time, author, image, image_alt, excerpt, content_json, status, created_at, updated_at) VALUES ('post-du-an-mam-cay-thanh-nien-180-cay-xanh-hoa-lac', 'du-an-mam-cay-thanh-nien-180-cay-xanh-hoa-lac', 'Mầm Cây Thanh Niên: Phủ xanh 180 cây bóng mát Hòa Lạc', 'HolaGreen · Sạch', 'moi-truong', '["sach"]', '2026-11-15', '15/11/2026', '3 phút đọc', 'Ban Dự Án Xanh HolaRise', '/assets/images/events/activity-tree-planting.jpg', 'Cận cảnh mầm cây xanh non được ươm trong đất ẩm màu mỡ dọc tuyến đường Hòa Lạc', '180 cây bàng Đài Loan và muồng hoàng yến đã được các bạn trẻ vun trồng dọc tuyến đường liên thôn tại Tân Xã, tạo bóng mát lâu dài.', '["Sáng Chủ Nhật 15/11, hơn 60 thanh niên và sinh viên từ các trường đại học tại Khu công nghệ cao Hòa Lạc đã cùng bắt tay thực hiện giai đoạn 2 của [dự án Mầm Cây Thanh Niên](/hoat-dong/#moi-truong).", "Đoàn đã trồng mới và cắm cọc bảo vệ cho 180 cây xanh bản địa dọc tuyến đường liên thôn Tân Xã. Mỗi cây đều được gắn thẻ ghi mã số nhóm chăm sóc và ngày trồng để các tình nguyện viên định kỳ tưới nước và theo dõi độ sinh trưởng.", "Hoạt động không chỉ tạo thêm bóng mát lâu dài cho bà con địa phương mà còn gắn kết người trẻ qua lao động thực tế, đúng tinh thần Small Beginnings, Great Impact trong [sứ mệnh cộng đồng HolaRise](/gioi-thieu/).", "Giai đoạn tiếp theo của dự án phủ xanh sẽ diễn ra vào tháng 12. Bạn có thể [đăng ký tham gia cuối tuần](/tham-gia/) để cùng góp thêm một mầm xanh cho Hòa Lạc."]', 'published', '2026-11-22T15:53:17Z', '2026-11-22T15:53:17Z');
INSERT OR IGNORE INTO posts (id, slug, title, category, category_slug, filters_json, date, date_display, read_time, author, image, image_alt, excerpt, content_json, status, created_at, updated_at) VALUES ('post-chien-dich-lam-sach-ven-ho-tan-xa-mua-thu-2026', 'chien-dich-lam-sach-ven-ho-tan-xa-mua-thu-2026', 'Cuối Tuần Xanh #18 Hồ Tân Xã: Thu gom 180 kg rác', 'HolaGreen · Sạch', 'moi-truong', '["sach"]', '2026-11-08', '08/11/2026', '2 phút đọc', 'Ban Điều Phối HolaRise', '/assets/images/events/activity-lake-cleanup.jpg', 'Đôi tay đeo găng vải thu gom và phân loại rác thải nhựa ven hồ Tân Xã vào buổi sáng', '52 thanh niên, sinh viên và học sinh đã cùng làm sạch 2km ven hồ Tân Xã và phân loại 180 kg rác trong sáng Chủ Nhật.', '["6h45 sáng Chủ Nhật 08/11, 52 bạn thanh niên, sinh viên và học sinh đã có mặt tại điểm hẹn ven hồ Tân Xã, Hòa Lạc để khởi động chiến dịch Cuối Tuần Xanh #18 thuộc [chương trình môi trường HolaGreen](/hoat-dong/#moi-truong).", "Ban Điều Phối chia thành 10 nhóm nhỏ để người mới đi lần đầu nhanh chóng làm quen, tương tự cách sắp xếp ở [lịch hoạt động cuối tuần tại Hòa Lạc](/workshop/). Mỗi nhóm được trang bị găng tay vải, kẹp gắp rác và túi phân loại riêng cho nhựa tái chế.", "Sau 2 giờ làm việc dọc 2 km bờ hồ Tân Xã, cả đoàn thu gom 180 kg rác thải, trong đó tách riêng 35 kg chai nhựa và vỏ lon bàn giao cho điểm tái chế địa phương.", "Hơn cả một tuyến đường sạch đẹp, buổi sáng cuối tuần mang lại những người bạn mới chân thành và tinh thần Small Beginnings, Great Impact gắn với [sứ mệnh và 4 giá trị của HolaRise](/gioi-thieu/)."]', 'published', '2026-11-22T15:53:17Z', '2026-11-22T15:53:17Z');
INSERT OR IGNORE INTO posts (id, slug, title, category, category_slug, filters_json, date, date_display, read_time, author, image, image_alt, excerpt, content_json, status, created_at, updated_at) VALUES ('post-workshop-tai-che-thuy-tinh-song-giam-nhua-hoa-lac', 'workshop-tai-che-thuy-tinh-song-giam-nhua-hoa-lac', 'Workshop HolaGreen #15: Tái chế thủy tinh & Sen đá bàn học', 'HolaGreen · Sạch', 'workshop', '["sach", "tu-te"]', '2026-11-01', '01/11/2026', '2 phút đọc', 'Ban Sáng Tạo HolaRise', '/assets/images/events/activity-glass-upcycling.jpg', 'Những chiếc lọ thủy tinh cũ được học sinh, sinh viên HolaRise tái chế thành chậu sen đá xanh xinh xắn', '85 chai lọ thủy tinh bỏ đi được sinh viên Hòa Lạc biến thành những chậu sen đá xanh mướt trang trí góc học tập.', '["Tại không gian sinh thái Tân Xã chiều Chủ Nhật 01/11, buổi workshop sáng tạo xanh HolaGreen #15 đã thu hút 42 học sinh và sinh viên cùng tham gia [chuỗi hoạt động thực hành bảo vệ môi trường](/hoat-dong/#workshop).", "Từ những chiếc lọ mứt, chai nước thủy tinh đã qua sử dụng do các bạn tình nguyện viên gom lại, mỗi người tự tay rửa sạch, quấn dây thừng mộc mạc và phối trộn đất dinh dưỡng để trồng một cây sen đá mini mang về bàn học.", "Buổi workshop giúp người trẻ nhận ra lối sống giảm rác thải không hề phức tạp mà bắt đầu từ những thói quen tái sử dụng gần gũi, sáng tạo và ngập tràn niềm vui.", "Danh sách các chủ đề workshop tiếp theo được cập nhật liên tục tại [lịch hoạt động cuối tuần HolaRise](/workshop/)."]', 'published', '2026-11-22T15:53:17Z', '2026-11-22T15:53:17Z');
INSERT OR IGNORE INTO posts (id, slug, title, category, category_slug, filters_json, date, date_display, read_time, author, image, image_alt, excerpt, content_json, status, created_at, updated_at) VALUES ('post-workshop-gieo-mam-tu-te-lan-toa-loi-song-tich-cuc', 'workshop-gieo-mam-tu-te-lan-toa-loi-song-tich-cuc', 'Workshop HolaHeart #14: Lòng biết ơn gia đình', 'HolaHeart · Biết ơn & Tử tế', 'workshop', '["biet-on", "tu-te"]', '2026-10-25', '25/10/2026', '2 phút đọc', 'Ban Nội Dung HolaRise', '/assets/images/events/activity-gratitude-workshop.jpg', 'Hoa lá khô ép và những tấm thiệp tri ân viết tay mộc mạc tại workshop HolaHeart Tân Xã', '38 bạn trẻ tại Hòa Lạc cùng lắng nghe câu chuyện về lòng biết ơn cha mẹ – thầy cô và tự tay làm thiệp lá khô gửi người thân.', '["Chiều Chủ Nhật 25/10 tại Tân Xã, Hòa Lạc, 38 học sinh và sinh viên đã tham dự buổi thứ 14 trong [chuỗi Workshop giá trị sống HolaHeart](/workshop/) với chủ đề \"Lòng Biết Ơn – Cội Nguồn Của Nhân Cách Đẹp\".", "Không gian buổi gặp gỡ mở đầu bằng những câu chuyện đời thường xúc động về sự hy sinh thầm lặng của cha mẹ, sự dìu dắt của thầy cô và [câu chuyện cộng đồng thanh niên Hòa Lạc](/gioi-thieu/).", "Ở phần thực hành, mỗi bạn tự tay làm một tấm thiệp ép lá khô viết lời cảm ơn gửi về gia đình, tiếp nối hành trình tử tế của [các chiến dịch thiện nguyện HolaRise](/hoat-dong/#workshop)."]', 'published', '2026-11-22T15:53:17Z', '2026-11-22T15:53:17Z');
INSERT OR IGNORE INTO posts (id, slug, title, category, category_slug, filters_json, date, date_display, read_time, author, image, image_alt, excerpt, content_json, status, created_at, updated_at) VALUES ('post-chuoi-workshop-lang-nghe-va-ket-noi-ban-dong-hanh', 'chuoi-workshop-lang-nghe-va-ket-noi-ban-dong-hanh', 'Vòng Tròn Lắng Nghe: Chữa lành và kết nối bạn trẻ xa nhà', 'HolaConnect · Tử tế & Sẻ chia', 'cong-dong', '["tu-te", "se-chia"]', '2026-10-18', '18/10/2026', '3 phút đọc', 'Ban Phụng Sự HolaRise', '/assets/images/events/activity-workshop-journal.jpg', 'Sổ tay ghi chép, bút viết và tài liệu sinh hoạt kết nối người trẻ tại Hòa Lạc', 'Buổi gặp gỡ ngoài trời giúp 45 bạn sinh viên mới lên Hòa Lạc tìm thấy sự đồng điệu, giải tỏa áp lực xa nhà.', '["Rời quê nhà lên Hòa Lạc học tập, nhiều bạn tân sinh viên thường đối mặt với cảm giác lạc lõng trong những tuần đầu tiên. Buổi gặp mặt \"Vòng Tròn Lắng Nghe\" thuộc [chương trình kết nối HolaConnect](/hoat-dong/#cong-dong) ra đời để tạo chiếc cầu nối ấm áp đó.", "Ngồi thành vòng tròn trên thảm cỏ xanh mát dưới những tán cây, các bạn cùng rèn luyện kỹ năng lắng nghe không phán xét, chia sẻ những khó khăn trong việc cân bằng giữa học tập và cuộc sống tự lập.", "Nhiều tình bạn đẹp và nhóm học tập cùng tiến đã được nhen nhóm ngay sau buổi gặp, chứng minh sức mạnh của sự thấu hiểu và chân thành trong [4 giá trị cốt lõi của cộng đồng](/gioi-thieu/#bo-loc-gia-tri).", "Bạn luôn có thể tìm thấy những người bạn đồng hành tích cực khi [tham gia hoạt động cuối tuần](/tham-gia/) cùng HolaRise."]', 'published', '2026-11-22T15:53:17Z', '2026-11-22T15:53:17Z');
INSERT OR IGNORE INTO posts (id, slug, title, category, category_slug, filters_json, date, date_display, read_time, author, image, image_alt, excerpt, content_json, status, created_at, updated_at) VALUES ('post-nhip-cau-yeu-thuong-trao-tu-sach-thach-that', 'nhip-cau-yeu-thuong-trao-tu-sach-thach-that', 'HolaConnect: Trao 152 sách cho thiếu nhi Hòa Lạc', 'HolaConnect · Sẻ chia', 'cong-dong', '["se-chia"]', '2026-10-04', '04/10/2026', '2 phút đọc', 'Ban Phụng Sự HolaRise', '/assets/images/events/activity-book-donation.jpg', 'Những chồng sách thiếu nhi và quà tặng học tập được chuẩn bị gửi tới các em nhỏ tại Hòa Lạc', '152 cuốn sách thiếu nhi và quà học tập do sinh viên Hòa Lạc đóng góp đã được trao tận tay các em nhỏ tại Tân Xã.', '["Đầu tháng 10, Cộng đồng HolaRise phát động đợt quyên góp \"Tủ Sách Thanh Niên Gửi Thiếu Nhi Hòa Lạc\" thuộc [chương trình phụng sự HolaConnect](/hoat-dong/#cong-dong) và nhận được 152 cuốn sách truyện, khoa học thường thức từ học sinh, sinh viên.", "Mỗi cuốn sách đều được bọc cẩn thận kèm lời chúc viết tay ở trang đầu. Trong buổi sáng trao tặng, tình nguyện viên cùng các em nhỏ đọc sách, chơi đố vui môi trường và chuẩn bị cho [các buổi workshop và giao lưu sắp tới](/workshop/).", "Toàn bộ danh mục sách và hình ảnh được lưu trữ công khai theo [nguyên tắc hoạt động minh bạch](/gioi-thieu/#minh-bach). Bạn có thể [đăng ký đồng hành đợt trao sách tiếp theo](/tham-gia/) ngay trên website."]', 'published', '2026-11-22T15:53:17Z', '2026-11-22T15:53:17Z');
INSERT OR IGNORE INTO posts (id, slug, title, category, category_slug, filters_json, date, date_display, read_time, author, image, image_alt, excerpt, content_json, status, created_at, updated_at) VALUES ('post-cam-nang-di-cuoi-tuan-xanh-lan-dau-cho-sinh-vien', 'cam-nang-di-cuoi-tuan-xanh-lan-dau-cho-sinh-vien', 'Cẩm nang Cuối Tuần Xanh: Đi một mình có bỡ ngỡ không?', 'HolaGreen · Sạch', 'moi-truong', '["sach", "tu-te"]', '2026-09-20', '20/09/2026', '3 phút đọc', 'Ban Điều Phối HolaRise', '/assets/images/events/activity-nature-trail.jpg', 'Lối đi rợp bóng cây xanh mát dẫn ra điểm hẹn làm sạch ven hồ Tân Xã', 'Hướng dẫn chi tiết từ trang phục, cách di chuyển đến quy trình ghép nhóm nhỏ cho người trẻ lần đầu tham gia Cuối Tuần Xanh.', '["Nhiều bạn sinh viên chia sẻ rằng trước khi tham gia buổi đầu tiên, các bạn từng ngập ngừng vì ''chưa quen ai và sợ đi một mình bỡ ngỡ''. Cẩm nang này được Ban Điều Phối đúc kết để giúp bạn hoàn toàn an tâm khi bắt đầu.", "Trước mỗi sáng hoạt động, bạn chỉ cần đăng ký qua biểu mẫu để nhận [thẻ check-in pass điện tử](/tham-gia/). Khi đến điểm hẹn ven hồ Tân Xã, điều phối viên sẽ đón bạn tại bàn tiếp nhận và ghép bạn vào nhóm nhỏ 4-5 người cùng trường hoặc cùng lứa tuổi.", "Về dụng cụ: CLB đã chuẩn bị sẵn găng tay bảo hộ dệt sợi, kẹp rác inox và túi phân loại. Bạn chỉ cần mặc quần áo thoải mái, đi giày thể thao và mang theo bình nước cá nhân để hạn chế đồ nhựa dùng một lần.", "Sau 2 tiếng lao động ngoài trời hít thở không khí trong lành, mọi người cùng ngồi lại uống trà, trò chuyện và ghi nhận chứng nhận tình nguyện theo đúng [quy chuẩn minh bạch của HolaRise](/gioi-thieu/#minh-bach)."]', 'published', '2026-11-22T15:53:17Z', '2026-11-22T15:53:17Z');
INSERT OR IGNORE INTO posts (id, slug, title, category, category_slug, filters_json, date, date_display, read_time, author, image, image_alt, excerpt, content_json, status, created_at, updated_at) VALUES ('post-ngay-hoi-sach-va-tuoi-tho-nha-van-hoa-thach-that', 'ngay-hoi-sach-va-tuoi-tho-nha-van-hoa-thach-that', 'Ngày Hội Sách & Tuổi Thơ: 200 cuốn sách tìm bạn đọc nhỏ', 'HolaConnect · Sẻ chia', 'cong-dong', '["se-chia", "tu-te"]', '2026-09-06', '06/09/2026', '3 phút đọc', 'Ban Phụng Sự HolaRise', '/assets/images/events/activity-children-drawings.jpg', 'Bút màu và những bức tranh vẽ ước mơ cây xanh của các em nhỏ tại buổi đọc sách', 'Buổi giao lưu đọc sách kết hợp vẽ tranh bảo vệ thiên nhiên thu hút hơn 40 em nhỏ cùng phụ huynh tại Thạch Thất.', '["Sáng Chủ Nhật đầu tháng 9 tại Nhà Văn Hóa thôn, ngày hội ''Sách & Tuổi Thơ'' thuộc [chương trình phụng sự HolaConnect](/hoat-dong/#cong-dong) đã diễn ra trong không khí rộn rã tiếng cười của các em nhỏ địa phương.", "Đội ngũ tình nguyện viên đã vận chuyển và sắp đặt 200 đầu sách truyện tranh giáo dục, khoa học thường thức và lịch sử danh nhân lên các kệ gỗ nhỏ để các em tự do chọn đọc.", "Bên cạnh giờ đọc sách, các em còn được tham gia cuộc thi vẽ tranh với chủ đề ''Hòa Lạc Xanh Trong Mắt Em'', sử dụng sáp màu hữu cơ và giấy vẽ tái chế để khắc họa tình yêu quê hương và cây xanh.", "Toàn bộ tranh vẽ và những lời cảm ơn viết tay của phụ huynh đã trở thành nguồn động viên to lớn cho các bạn sinh viên tiếp tục mở rộng [các dự án cộng đồng ý nghĩa](/workshop/)."]', 'published', '2026-11-22T15:53:17Z', '2026-11-22T15:53:17Z');
INSERT OR IGNORE INTO posts (id, slug, title, category, category_slug, filters_json, date, date_display, read_time, author, image, image_alt, excerpt, content_json, status, created_at, updated_at) VALUES ('post-hanh-trinh-uom-mam-xanh-tu-vuon-cay-giong-hoa-lac', 'hanh-trinh-uom-mam-xanh-tu-vuon-cay-giong-hoa-lac', 'Vườn Ươm Mầm Xanh: 300 bầu cây sẵn sàng phủ bóng', 'HolaGreen · Sạch', 'moi-truong', '["sach"]', '2026-08-23', '23/08/2026', '3 phút đọc', 'Ban Dự Án Xanh HolaRise', '/assets/images/events/activity-tree-seedlings.jpg', 'Những khay bầu cây giống non xanh tươi đang được chăm sóc cẩn thận tại vườn ươm', 'Giai đoạn chuẩn bị giống cây bản địa và đất mùn hữu cơ đã hoàn tất, hướng tới chiến dịch phủ xanh các tuyến đường vào cuối năm.', '["Để chuẩn bị cho chiến dịch phủ xanh quy mô lớn vào quý 4, nhóm dự án Môi trường HolaGreen đã phối hợp cùng các kỹ sư nông nghiệp địa phương thiết lập khu vườn ươm mầm xanh với 300 bầu cây giống bản địa.", "Các giống cây được lựa chọn kỹ càng bao gồm bàng Đài Loan, muồng hoàng yến và cây bóng mát thân gỗ chịu hạn tốt, phù hợp với thổ nhưỡng gò đồi đất đỏ đặc trưng của vùng Hòa Lạc.", "Mỗi tuần, các nhóm sinh viên luân phiên nhau tưới nước, tỉa cành và phối trộn phân bón compost hữu cơ để đảm bảo cây giống đạt chuẩn chiều cao và độ bén rễ trước khi xuất vườn.", "Hoạt động ươm giống thể hiện cam kết làm việc bài bản, bền bỉ và trách nhiệm dài hạn của [cộng đồng thanh niên HolaRise](/gioi-thieu/) vì một Hòa Lạc xanh tươi bền vững."]', 'published', '2026-11-22T15:53:17Z', '2026-11-22T15:53:17Z');
INSERT OR IGNORE INTO events (id, kind, type, filters_json, date, date_display, time, location, fee, seats, title, summary, highlights_json, participants, image, image_alt, status, sort_order, created_at, updated_at) VALUES ('ws-long-biet-on-va-song-xanh', 'upcoming', 'HolaHeart · Biết ơn & Tử tế', '["biet-on", "tu-te"]', '2026-11-29', 'CN, 29/11/2026', '08:30 – 11:00', 'Hòa Lạc, Hà Nội', 'Miễn phí', 'Còn 18/40 chỗ', 'Workshop: Lòng Biết Ơn & Sự Tử Tế Giữa Đời Thường', 'Cùng sẻ chia về lòng biết ơn cha mẹ – thầy cô, tự tay viết thiệp tri ân và tái chế lọ thủy tinh thành chậu cây xanh.', '["Sẻ chia lòng biết ơn", "Tái chế chậu cây xanh", "Viết thiệp tri ân"]', '', '/assets/images/events/activity-gratitude-workshop.jpg', 'Bàn hoa lá khô ép thủ công và thiệp tri ân tại workshop HolaHeart', 'published', 0, '2026-11-22T15:53:17Z', '2026-11-22T15:53:17Z');
INSERT OR IGNORE INTO events (id, kind, type, filters_json, date, date_display, time, location, fee, seats, title, summary, highlights_json, participants, image, image_alt, status, sort_order, created_at, updated_at) VALUES ('cleanup-ho-tan-xa-thang-12', 'upcoming', 'HolaGreen · Sạch', '["sach"]', '2026-12-06', 'CN, 06/12/2026', '06:45 – 09:15', 'Ven Hồ Tân Xã, Hòa Lạc', 'Miễn phí (Có sẵn dụng cụ)', 'Mở đăng ký', 'Cuối Tuần Xanh #19: Làm Sạch & Phân Loại Rác Hồ Tân Xã', 'Dọn sạch bờ cỏ ven hồ Tân Xã sáng Chủ Nhật, phân loại chai nhựa tái chế và kết nối những người bạn mới tích cực.', '["Có sẵn găng tay & kẹp rác", "Ghép nhóm cho người mới", "Chứng nhận tình nguyện"]', '', '/assets/images/events/activity-lake-cleanup.jpg', 'Đôi tay đeo găng bảo hộ nhặt rác và phân loại chai nhựa ven hồ Tân Xã', 'published', 1, '2026-11-22T15:53:17Z', '2026-11-22T15:53:17Z');
INSERT OR IGNORE INTO events (id, kind, type, filters_json, date, date_display, time, location, fee, seats, title, summary, highlights_json, participants, image, image_alt, status, sort_order, created_at, updated_at) VALUES ('ws-truyen-cam-hung-va-ket-noi', 'upcoming', 'HolaConnect · Tử tế & Sẻ chia', '["tu-te", "se-chia"]', '2026-12-13', 'CN, 13/12/2026', '14:30 – 17:00', 'Hòa Lạc, Hà Nội', 'Miễn phí', 'Còn 25/35 chỗ', 'Workshop: Nghệ Thuật Lắng Nghe & Khát Vọng Tuổi Trẻ', 'Thực hành giao tiếp chân thành, kết nối bạn đồng hành lành mạnh tại Hòa Lạc và định hướng mục tiêu sống có ích.', '["Kỹ năng lắng nghe", "Kết nối bạn mới", "Tặng sổ tay Tử Tế"]', '', '/assets/images/events/activity-workshop-journal.jpg', 'Sổ tay Tử Tế và tài liệu sinh hoạt tại buổi giao lưu kết nối bạn trẻ', 'published', 2, '2026-11-22T15:53:17Z', '2026-11-22T15:53:17Z');
INSERT OR IGNORE INTO events (id, kind, type, filters_json, date, date_display, time, location, fee, seats, title, summary, highlights_json, participants, image, image_alt, status, sort_order, created_at, updated_at) VALUES ('ws-tai-che-sen-da-thang-12', 'upcoming', 'HolaGreen · Tái chế & Sáng tạo', '["sach", "tu-te"]', '2026-12-20', 'CN, 20/12/2026', '09:00 – 11:30', 'Không gian Xanh Tân Xã, Hòa Lạc', 'Miễn phí (Tặng sen đá & lọ mầm)', 'Còn 20/35 chỗ', 'Workshop: Tái Chế Thủy Tinh & Sống Xanh Bền Vững', 'Học cách làm sạch chai lọ thủy tinh phế liệu, phối đất trồng sen đá mini trang trí bàn học và thực hành lối sống giảm rác thải.', '["Mang về chậu sen đá", "Phối đất trồng mầm", "Thực hành Zero Waste"]', '', '/assets/images/events/activity-glass-upcycling.jpg', 'Chậu sen đá mini xanh mướt trồng trong lọ thủy tinh tái chế', 'published', 3, '2026-11-22T15:53:17Z', '2026-11-22T15:53:17Z');
